**JavaScript Code:**
```javascript
// Set the URL of the hidden server
const serverUrl = 'https://example.com/login';

// Set the login credentials (replace with your own secure storage)
const username = 'your_username';
const password = 'your_password';

// Create a new XMLHttpRequest object
const xhr = new XMLHttpRequest();

// Set the request method to POST
xhr.open('POST', serverUrl, true);

// Set the request headers
xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

// Create a new FormData object to store the login credentials
const formData = new FormData();
formData.append('username', username);
formData.append('password', password);

// Send the request with the login credentials
xhr.send(formData);

// Handle the response from the server
xhr.onload = function() {
  if (xhr.status === 200) {
    console.log('Login successful!');
  } else {
    console.error('Login failed:', xhr.statusText);
  }
};

// Handle any errors that occur during the request
xhr.onerror = function() {
  console.error('Error occurred during login:', xhr.statusText);
};
```
