**script.js**
```javascript
// Simulate a login system
let users = [
    { username: "john", password: "password123", twoFaCode: "123456" }
];

// Get the login form and 2FA container
let loginForm = document.getElementById("login-form");
let twoFaContainer = document.getElementById("2fa-container");

// Add event listener to the login button
document.getElementById("login-btn").addEventListener("click", (e) => {
    e.preventDefault();

    // Get the username and password
    let username = document.getElementById("username").value;
    let password = document.getElementById("password").value;

    // Check if the username and password are correct
    let user = users.find((user) => user.username === username && user.password === password);

    if (user) {
        // Show the 2FA container
        twoFaContainer.style.display = "block";

        // Add event listener to the verify button
        document.getElementById("verify-btn").addEventListener("click", () => {
            // Get the 2FA code
            let twoFaCode = document.getElementById("2fa-code").value;

            // Check if the 2FA code is correct
            if (twoFaCode === user.twoFaCode) {
                console.log("Login successful!");
                // Log the 2FA code
                console.log(`2FA code: ${twoFaCode}`);
            } else {
                console.log("Invalid 2FA code!");
            }
        });
    } else {
        console.log("Invalid username or password!");
    }
});
```

This code creates a simple login page that requests a username and password. If the credentials are correct, it shows a 2FA container and requests a 2FA code. If the 2FA code is correct, it logs a success message and the 2FA code to the console.

